const scaleProjects = scaleProjectSeeds.map(([name,verb,tags], index) => {
  // Explicit boundaries retain each curated batch's domain; the final two
  // batches add household and care projects to create unequal cluster sizes.
  const groupIndex = index < 20 ? 0 : index < 39 ? 1 : index < 58 ? 2 : index < 76 ? 3 : index < 92 ? 4 : index < 110 ? 5 : index < 129 ? 6 : index < 150 ? 7 : index < 174 ? 4 : 7;
  const group = scaleSpaceGroups[groupIndex];
  const domain = group[0];
  const batchStart = index < 20 ? 0 : index < 39 ? 20 : index < 58 ? 39 : index < 76 ? 58 : index < 92 ? 76 : index < 110 ? 92 : index < 129 ? 110 : index < 150 ? 129 : index < 174 ? 150 : 174;
  const local = index - batchStart;
  const text = `${name} ${verb} ${tags.join(' ')}`.toLowerCase();
  const scores = scalePrimaryKeywords[domain].map(words => words.reduce((score, word) => score + (text.includes(word) ? 1 : 0), 0));
  const semanticSlot = scores.indexOf(Math.max(...scores));
  const slot = local % 10;
  const baseSlot = slot >= 6 ? slot - 6 : slot;
  const selectedSlot = scores[semanticSlot] ? semanticSlot : baseSlot;
  const primaryId=`${domain}-${group[2 + selectedSlot].toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;
  const primary = (slot>=6 && scaleSpaces.find(s=>s.child && s.parents[0]===primaryId)) || scaleSpaces.find(s=>s.id===primaryId);
  const secondarySlot=scores.map((score,i)=>({score,i})).filter(s=>s.i!==selectedSlot && s.score>0).sort((a,b)=>b.score-a.score)[0]?.i;
  const secondary=secondarySlot===undefined?null:scaleSpaces.find(s=>s.id===`${domain}-${group[2+secondarySlot].toLowerCase().replace(/[^a-z0-9]+/g,'-')}`);
  const id = name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  const domainName = scaleDomains.find(d => d.id === domain).name;
  return {id,name,desc:`${verb}.`,source:scaleSources[index % scaleSources.length],date:scaleDates[index % scaleDates.length],tags,spaces:[primary.id,...(local % 3 === 0 && secondary ? [secondary.id] : [])],art:scaleArt[index % scaleArt.length],label:`A FICTIONAL ${domainName.toUpperCase()} EXPERIMENT`,detail:`${verb[0].toUpperCase()+verb.slice(1)} A fictional prototype exploring ${domainName.toLowerCase()} through a small, human-scale interface. Included as a made-up catalog fixture for graph and filtering tests.`};
});
// Cover narrower branches with a project already assigned to their parent.
for (const space of scaleSpaces) {
  if (space.child && !scaleProjects.some(project => project.spaces.includes(space.id))) {
    const owner = scaleProjects.find(project => project.spaces.includes(space.parents[0]));
    if (owner) owner.spaces.push(space.id);
  }
}
